-- Executed NumPy oracle for transposed/Fortran order and 64-bit integer ranges.
local np=require('luaray_core')
assert(np._version=='0.102.0-dev')
local passed=0
local failures=0
local function eq(a,b)
 if type(a)~=type(b) then return false end
 if type(a)=='table' then
  if #a~=#b then return false end
  for i=1,#a do if not eq(a[i],b[i]) then return false end end
  return true
 end
 return a==b
end
local function check(v,dtype,shape,expect,tail,r,case)
 local ok=true
 if #shape==0 and type(v)~='userdata' then ok=eq(v,expect)
 else
  ok=type(v)=='userdata' and v.dtype==dtype and eq(v.shape,shape) and eq(v:tolist(),expect)
 end
 if not ok or r:raw_hex()~=tail then
  failures=failures+1
  if failures<=8 then
   print('FAIL '..case..' values='..tostring(ok)..' pcg='..tostring(r:raw_hex()==tail))
  end
 else passed=passed+1 end
end
do local r=np.random.default_rng(42);local v=r:integers(np.transpose(np.array({{0,3},{1,4},{2,5}},"int64")),np.transpose(np.array({{4,10},{6,12},{8,14}},"int64")),nil,"int8",false);check(v,"int8",{2,3},{{2,1,7},{3,10,13}},"705a5661a791ffc1",r,1) end
